#!/usr/bin/env python3\n\nimport sys\nimport json\nimport base64\nimport datetime\n\ndef encode_message(message: str) -> dict:\n    """Return a dict with original, base64‑encoded payload and UTC timestamp."""\n    encoded = base64.b64encode(message.encode()).decode()\n    timestamp = datetime.datetime.utcnow().isoformat() + "Z"\n    return {\n        "original": message,\n        "encoded": encoded,\n        "timestamp": timestamp,\n    }\n\ndef main():\n    # If data is piped in, read from stdin\n    if not sys.stdin.isatty():\n        message = sys.stdin.read().strip()\n    else:\n        # Otherwise expect at least one CLI argument\n        if len(sys.argv) > 1:\n            message = " ".join(sys.argv[1:]).strip()\n        else:\n            print("Usage: echo \"msg\" | docker run -i <image> OR docker run <image> \"msg\"")\n            sys.exit(1)\n    result = encode_message(message)\n    print(json.dumps(result))\n\nif __name__ == "__main__":\n    main()
